def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {v: sum(row.count(v) for row in grid) for v in set(v for row in grid for v in row)}
    marker = min(counts, key=counts.get)
    background = max(counts, key=counts.get)

    # Complete short gaps between successive stroke marks on rows/columns.
    for r in range(h):
        marks = [c for c, v in enumerate(grid[r]) if v == marker]
        if len(marks) >= 3:
            for a, b in zip(marks, marks[1:]):
                for c in range(a + 1, b):
                        if grid[r][c] == background:
                            out[r][c] = 2
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == marker]
        if len(marks) >= 3:
            for a, b in zip(marks, marks[1:]):
                for r in range(a + 1, b):
                        if grid[r][c] == background:
                            out[r][c] = 2
    return out

